export type NatureCategory =
  | 'conifer' | 'broadleaf'
  | 'rock_large' | 'rock_tall' | 'rock_small'
  | 'bush' | 'plant' | 'grass' | 'flower' | 'mushroom'
  | 'log' | 'stump' | 'camp' | 'sign';

/** Measured facts about one Kenney GLB, generated by tools/nature_catalog.py from the real file. */
export interface NatureAsset {
  /** File name inside assets/kenney_nature-kit/Models/GLTF format/. */
  readonly file: string;
  readonly bytes: number;
  readonly sha1: string;
  readonly category: NatureCategory;
  /** Lowest corner of the model's bounding box (native units). */
  readonly min: readonly [number, number, number];
  /** Bounding-box size (native units): width (x), height (y), depth (z). */
  readonly size: readonly [number, number, number];
  /** Horizontal centre of the bounding box (x, z). */
  readonly center: readonly [number, number];
  readonly materials: readonly string[];
  /** Trees only: radius of the trunk near the ground (native units). */
  readonly trunkRadius?: number;
  readonly trunkCenter?: readonly [number, number];
}
